public class FitZoneMembershipDesk {
    interface MembershipPlan{double calculateFee();String getName();}static class MonthlyPlan implements MembershipPlan{public double calculateFee(){return 1000;}public String getName(){return "Monthly";}}static class QuarterlyPlan implements MembershipPlan{public double calculateFee(){return 2700;}public String getName(){return "Quarterly";}}static class AnnualPlan implements MembershipPlan{public double calculateFee(){return 9000;}public String getName(){return "Annual";}}
    enum Status{ACTIVE,FROZEN,EXPIRED}static class Membership{String name;MembershipPlan plan;Status status=Status.ACTIVE;Membership(String n,MembershipPlan p){name=n;plan=p;System.out.printf("%s membership created for %s. Fee: ₹%.2f. Status: Active.%n",p.getName(),n,p.calculateFee());}void checkIn(){System.out.println(status==Status.ACTIVE?name+" checked in successfully.":"Check-in denied: "+name+"'s membership is "+status+".");}void freeze(){if(status==Status.ACTIVE){status=Status.FROZEN;System.out.println(name+"'s membership frozen. Status: Frozen.");}}void unfreeze(){if(status==Status.FROZEN){status=Status.ACTIVE;System.out.println(name+"'s membership unfrozen. Status: Active.");}}void expire(){status=Status.EXPIRED;System.out.println(name+"'s membership expired. Status: Expired.");}}
    public static void main(String[] args){Membership m=new Membership("Asha",new QuarterlyPlan());m.checkIn();m.freeze();m.checkIn();m.unfreeze();m.checkIn();}
}